# Change `read-retry-budget` (fixture): a cache lookup retries at most twice before the
# database path is taken. The wrapper is the behaviour; the test observes attempts and
# the single database fallback.
READ_ATTEMPTS_BUDGET = 2


class BoundedCacheRetry:
    """Retry a failing cache at most `budget` times, then report the cache as unavailable."""

    def __init__(self, inner: CacheAdapter, budget: int = READ_ATTEMPTS_BUDGET) -> None:
        if budget < 1:
            raise ValueError("budget must be at least one attempt")
        self._inner = inner
        self.budget = budget
        self.attempts = 0

    def get(self, product_id: str) -> Optional[Dict[str, Any]]:
        last: Optional[BaseException] = None
        for _ in range(self.budget):
            self.attempts += 1
            try:
                return self._inner.get(product_id)
            except (RuntimeError, TimeoutError, OSError) as exc:
                last = exc
        raise last if last is not None else RuntimeError("cache produced no attempt")
